import { CELL_SIZE } from '../config';

/**
 * Zentralisierte Konfiguration für das "RB 54"-Zug-Event.
 * Alle Zahlenwerte sind hier änderbar – keine Magic Numbers im übrigen Code.
 */
export const TRAIN = {
  /** Fahrgeschwindigkeit in px/s */
  SPEED:           600,

  /** Visuelle Breite = 2 × CELL_SIZE = 64 px, exakt auf dem Gleis-Raster */
  VISUAL_WIDTH:    CELL_SIZE*2,        // 64

  /** Arcade-Physics-Hitbox-Breite – schmaler als Grafik (kein unfairer Randtod) */
  HITBOX_WIDTH:    44,

  /** Länge der Lokomotive in px */
  LOCO_HEIGHT:     CELL_SIZE * 4,    // 96

  /** Länge eines Waggons in px */
  WAGON_HEIGHT:    CELL_SIZE * 8,   

  /** Anzahl Waggons hinter der Lokomotive */
  WAGON_COUNT:     12,

  /** Lücke zwischen Lok und erstem Waggon sowie zwischen Waggons in px */
  SEGMENT_GAP:     4,

  /** Gesamt-HP des Zugs (Shared Pool, Lok + alle Waggons zusammen) */
  HP_MAX:          300,

  /** Frags, die dem Last-Hit-Spieler gutgeschrieben werden */
  KILL_FRAGS:      1,

  /**
   * Erste Einfahrt in Modi ohne Map-Konfiguration (Deathmatch, Team-Deathmatch, Capture the Beer),
   * in ms nach Rundenstart. Coop-Defense-Maps konfigurieren das Zug-Event stattdessen selbst
   * Coop-Defense-Maps steuern Zug-Events über `mapEvents`.
   */
  DEFAULT_FIRST_ARRIVAL_MS: 10_000,

  /** Pause zwischen Verlassen der Arena und nächster Einfahrt in denselben Modi. */
  DEFAULT_REPEAT_AFTER_EXIT_MS: 10_000,

  /** Streifenhöhe in px für den Waggon-Geschwindigkeitseffekt */
  WAGON_STRIPE_H:  8,
  /** Maximale zufaellige Verzoegerung zwischen den Waggon-Detonationen. */
  EXPLOSION_WAGON_DELAY_MAX_MS: 220,
  /** Abstand der grossen Mittel-Detonation zum spaetesten Waggon. */
  EXPLOSION_CENTER_DELAY_MS:     260,

  // ── Beleuchtung (nur im Nachtprofil aktiv) ────────────────────────────────
  /** Querversatz der beiden Frontscheinwerfer von der Gleismitte, wie beim Vorbild. */
  HEADLIGHT_OFFSET_X: 18,
  /** Längsversatz der Scheinwerfer vor die Lokmitte – knapp hinter der Nasenspitze. */
  HEADLIGHT_OFFSET_Y: CELL_SIZE * 2 - 6,
  /** Querversatz der Fensterlichter: an der Kante des Wagenkastens (Breite/2 = 32). */
  WINDOW_LIGHT_OFFSET_X: 28,
  /** Längsversatz der Fensterlichter zur Waggonmitte; die Enden bleiben dunkel. */
  WINDOW_LIGHT_OFFSETS_Y: [-78, 0, 78],
  /** Querversatz der beiden Lok-Kabinenfenster – an der Seitenkante wie die Waggons. */
  LOCO_WINDOW_LIGHT_OFFSET_X: 26,
  /**
   * Längsversatz der Lok-Kabinenfenster zur Lokmitte, in Fahrtrichtung. Die Kabine mit
   * den seitlichen Fenstern sitzt vorne, direkt hinter den Scheinwerfern – wie beim
   * Vorbild. Wert relativ zur Fahrtrichtung (siehe `frontRelative`).
   */
  LOCO_WINDOW_LIGHT_OFFSET_Y: 22,

  /**
   * Pseudo-Attacker-ID für Zug-Instakills.
   * Verhindert, dass ein echter Spieler einen Frag bekommt.
   */
  TRAIN_KILLER_ID: '__train__',

  /** Schaden pro Tick wenn ein Dachs unter dem Zug buddelt */
  BURROW_DAMAGE_PER_TICK:         40,

  /** Millisekunden zwischen zwei Buddel-Schaden-Ticks */
  BURROW_DAMAGE_TICK_INTERVAL_MS: 100,

  /** Zusätzliche Gnadenfrist für Knockback-Frags nach Ende des aktiven Impulses */
  PLAYER_PUSH_KILL_CREDIT_GRACE_MS: 160,
} as const;
